"""JSON-backed registry of named connector configurations."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from agentic_odi_connectors.models import ConnectorConfig


class UnknownConnectorKindError(ValueError):
    def __init__(self, kind: str) -> None:
        self.kind = kind
        super().__init__(f"Unknown connector kind: {kind}")


class DuplicateConnectorError(ValueError):
    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"Connector already exists: {name}")


class ConnectorNotFoundError(ValueError):
    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"Connector not found: {name}")


def _known_kinds() -> set[str]:
    from agentic_odi_connectors.factory import known_kinds

    return known_kinds()


class ConnectorRegistry:
    """Persists connector configs to a JSON file."""

    def __init__(self, path: Path) -> None:
        self.path = path

    def add(self, config: ConnectorConfig) -> None:
        if config.kind not in _known_kinds():
            raise UnknownConnectorKindError(config.kind)
        connectors = self._load()
        if any(existing.name == config.name for existing in connectors):
            raise DuplicateConnectorError(config.name)
        connectors.append(config)
        self._save(connectors)

    def list_all(self) -> list[ConnectorConfig]:
        return self._load()

    def get(self, name: str) -> ConnectorConfig:
        for config in self._load():
            if config.name == name:
                return config
        raise ConnectorNotFoundError(name)

    def _load(self) -> list[ConnectorConfig]:
        if not self.path.exists():
            return []
        with self.path.open(encoding="utf-8") as handle:
            payload: dict[str, Any] = json.load(handle)
        raw_connectors = payload.get("connectors", [])
        return [ConnectorConfig.model_validate(item) for item in raw_connectors]

    def _save(self, connectors: list[ConnectorConfig]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = {"connectors": [item.model_dump(mode="json") for item in connectors]}
        with self.path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2)
            handle.write("\n")

"""CLI adapter for listing, adding, checking, and ingesting external connectors."""

from __future__ import annotations

import asyncio
import json
import os
from pathlib import Path
from typing import TYPE_CHECKING

import typer

from agentic_odi_cli.backend import run_tool
from agentic_odi_cli.render import render_saved

# The connectors package eagerly imports fastmcp via ``connectors/__init__``.
# Import it lazily so that merely loading the CLI (e.g. ``odi --version``) does
# not pay the fastmcp/mcp import cost. The wrappers below keep stable module
# attributes for tests to monkeypatch.
if TYPE_CHECKING:
    from agentic_odi_connectors.mapping import EvidenceDraft
    from agentic_odi_connectors.models import ConnectorConfig
    from agentic_odi_connectors.protocol import Connector
    from agentic_odi_connectors.registry import ConnectorRegistry
    from agentic_odi_connectors.sink import IngestSink

connectors_app = typer.Typer(
    name="connectors",
    help="Connect Agentic ODI to external systems.",
    no_args_is_help=True,
)


def build_connector(config: ConnectorConfig) -> Connector:
    from agentic_odi_connectors.factory import build_connector as _build_connector

    return _build_connector(config)


def get_default_sink() -> IngestSink:
    from agentic_odi_connectors.sink import get_default_sink as _get_default_sink

    return _get_default_sink()


def drafts_from_batch(
    batch,
    *,
    job_id: str | None = None,
    step_id: str | None = None,
    outcome_id: str | None = None,
) -> list[EvidenceDraft]:
    from agentic_odi_connectors.mapping import drafts_from_batch as _drafts_from_batch

    return _drafts_from_batch(batch, job_id=job_id, step_id=step_id, outcome_id=outcome_id)


def _config_path(config: Path | None) -> Path:
    if config is not None:
        return config
    env = os.getenv("AGENTIC_ODI_CONNECTORS_FILE")
    if env:
        return Path(env)
    return Path.cwd() / ".agentic-odi" / "connectors.json"


def _registry(config: Path | None) -> ConnectorRegistry:
    from agentic_odi_connectors.registry import ConnectorRegistry

    return ConnectorRegistry(_config_path(config))


def _parse_headers(values: list[str] | None) -> dict[str, str]:
    headers: dict[str, str] = {}
    for raw in values or []:
        key, separator, value = raw.partition("=")
        if not separator or not key.strip():
            typer.echo(f"Error: invalid header '{raw}', expected KEY=VALUE", err=True)
            raise typer.Exit(code=1)
        headers[key.strip()] = value.strip()
    return headers


ConfigOption = typer.Option(
    None,
    "--config",
    help="Path to the connectors JSON registry.",
    envvar="AGENTIC_ODI_CONNECTORS_FILE",
)

_CONNECTOR_TIMEOUT = 30.0


def _connector_timeout() -> float:
    raw = os.getenv("AGENTIC_ODI_CONNECTOR_TIMEOUT")
    if not raw:
        return _CONNECTOR_TIMEOUT
    try:
        return float(raw)
    except ValueError:
        return _CONNECTOR_TIMEOUT


def _run(coro, name: str):
    """Run a connector coroutine with a bounded timeout and clean failure."""
    timeout = _connector_timeout()
    try:
        return asyncio.run(asyncio.wait_for(coro, timeout=timeout))
    except asyncio.TimeoutError as exc:
        typer.echo(f"Error: connector '{name}' timed out after {timeout:.0f}s", err=True)
        raise typer.Exit(code=1) from exc


@connectors_app.command("list")
def list_connectors(
    config: Path | None = ConfigOption,
) -> None:
    """List configured external connectors."""
    items = _registry(config).list_all()
    if not items:
        typer.echo("No connectors configured.")
        return
    for item in items:
        status = "enabled" if item.enabled else "disabled"
        typer.echo(f"{item.name}\t{item.kind}\t{status}")


@connectors_app.command("catalog")
def catalog_presets(
    area: str | None = typer.Option(None, "--area", help="Filter by capability area."),
    as_json: bool = typer.Option(False, "--json", help="Emit JSON instead of a table."),
) -> None:
    """Browse ready-to-use MCP server presets for common ODI workflows."""
    from agentic_odi_connectors.catalog import AREA_LABELS, UnknownAreaError, list_presets

    try:
        presets = list_presets(area)
    except UnknownAreaError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    if as_json:
        typer.echo(json.dumps([preset.model_dump() for preset in presets], indent=2))
        return
    current_area: str | None = None
    for preset in presets:
        if preset.area != current_area:
            if current_area is not None:
                typer.echo()
            current_area = preset.area
            typer.echo(f"{AREA_LABELS[preset.area]} ({preset.area})")
        if preset.auth == "oauth":
            auth = "oauth"
        elif preset.env_vars:
            auth = "api key"
        else:
            auth = "none"
        line = f"  {preset.id:<12} {preset.label:<22} {auth:<8} {preset.url}"
        if preset.env_vars:
            line += f"  [{', '.join(preset.env_vars)}]"
        typer.echo(line)
    typer.echo("\nAdd one with: agentic-odi connectors add mcp --preset <id>")


def _mcp_connector_config(
    *,
    name: str | None,
    url: str | None,
    preset_id: str | None,
    tools: list[str] | None,
) -> ConnectorConfig:
    from agentic_odi_connectors.catalog import (
        UnknownPresetError,
        connector_config_from_preset,
        get_preset,
    )
    from agentic_odi_connectors.models import ConnectorConfig

    if preset_id is not None:
        try:
            preset = get_preset(preset_id)
        except UnknownPresetError as exc:
            typer.echo(f"Error: {exc}", err=True)
            raise typer.Exit(code=1) from exc
        return connector_config_from_preset(preset, name=name, url=url, tools=tools)
    if not url:
        typer.echo("Error: --url is required for MCP connectors (or pass --preset).", err=True)
        raise typer.Exit(code=1)
    if not name:
        typer.echo("Error: --name is required for MCP connectors.", err=True)
        raise typer.Exit(code=1)
    settings: dict[str, object] = {"url": url}
    if tools:
        settings["tools"] = tools
    return ConnectorConfig(name=name, kind="mcp", settings=settings)


@connectors_app.command("add")
def add_connector(
    kind: str = typer.Argument(..., help="Connector kind (mcp, rest, or webhook)."),
    name: str | None = typer.Option(
        None, "--name", help="Unique connector name (defaults to the preset id)."
    ),
    url: str | None = typer.Option(
        None, "--url", help="Endpoint URL (required unless --preset is given)."
    ),
    preset: str | None = typer.Option(
        None, "--preset", help="Preset id from 'connectors catalog'."
    ),
    tool: list[str] | None = typer.Option(  # noqa: B008
        None,
        "--tool",
        help="MCP tool to call during ingest. Repeatable.",
    ),
    method: str | None = typer.Option(None, "--method", help="HTTP method for REST/webhook."),
    header: list[str] | None = typer.Option(  # noqa: B008
        None, "--header", help="HTTP header as KEY=VALUE. Repeatable."
    ),
    records_key: str | None = typer.Option(
        None, "--records-key", help="Dot path to the record list in the response."
    ),
    config: Path | None = ConfigOption,
) -> None:
    """Register a new external connector, optionally from a known preset."""
    from agentic_odi_connectors.models import ConnectorConfig
    from agentic_odi_connectors.registry import DuplicateConnectorError, UnknownConnectorKindError

    if preset is not None and kind != "mcp":
        typer.echo("Error: --preset is only supported for MCP connectors.", err=True)
        raise typer.Exit(code=1)
    if kind == "mcp":
        connector_config = _mcp_connector_config(name=name, url=url, preset_id=preset, tools=tool)
    elif kind in {"rest", "webhook"}:
        if not name:
            typer.echo("Error: --name is required.", err=True)
            raise typer.Exit(code=1)
        if not url:
            typer.echo(f"Error: --url is required for {kind.upper()} connectors.", err=True)
            raise typer.Exit(code=1)
        settings: dict[str, object] = {"url": url}
        if method:
            settings["method"] = method.upper()
        headers = _parse_headers(header)
        if headers:
            settings["headers"] = headers
        if records_key:
            settings["records_key"] = records_key
        connector_config = ConnectorConfig(name=name, kind=kind, settings=settings)
    else:
        if not name:
            typer.echo("Error: --name is required.", err=True)
            raise typer.Exit(code=1)
        connector_config = ConnectorConfig(name=name, kind=kind, settings={})
    try:
        _registry(config).add(connector_config)
    except DuplicateConnectorError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    except UnknownConnectorKindError as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    typer.echo(f"Added {kind} connector '{connector_config.name}'.")
    env_vars = connector_config.settings.get("env_vars") or []
    if env_vars:
        typer.echo(f"Set {', '.join(str(item) for item in env_vars)} before health or ingest.")
    if connector_config.settings.get("auth") == "oauth":
        typer.echo("This server uses OAuth; the browser consent flow runs on first health/ingest.")


@connectors_app.command("health")
def health_connector(
    name: str = typer.Option(..., "--name", help="Connector name."),
    config: Path | None = ConfigOption,
) -> None:
    """Check whether a connector can reach its external system."""
    from agentic_odi_connectors.registry import ConnectorNotFoundError, UnknownConnectorKindError

    try:
        connector_config = _registry(config).get(name)
        connector = build_connector(connector_config)
    except (ConnectorNotFoundError, UnknownConnectorKindError) as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    status = _run(connector.health(), name)
    typer.echo(status.model_dump_json())
    if not status.ok:
        raise typer.Exit(code=1)


@connectors_app.command("ingest")
def ingest_connector(
    name: str = typer.Option(..., "--name", help="Connector name."),
    job_id: str | None = typer.Option(None, "--job-id", help="Link evidence to a Job."),
    step_id: str | None = typer.Option(None, "--step-id", help="Link evidence to a Step."),
    outcome_id: str | None = typer.Option(
        None, "--outcome-id", help="Link evidence to a desired Outcome."
    ),
    config: Path | None = ConfigOption,
) -> None:
    """Ingest connector records and optionally map them into ODI evidence."""
    from agentic_odi_connectors.registry import ConnectorNotFoundError, UnknownConnectorKindError

    try:
        connector_config = _registry(config).get(name)
        connector = build_connector(connector_config)
    except (ConnectorNotFoundError, UnknownConnectorKindError) as exc:
        typer.echo(f"Error: {exc}", err=True)
        raise typer.Exit(code=1) from exc
    batch = _run(connector.ingest(), name)
    get_default_sink().append(batch)
    typer.echo(batch.model_dump_json())
    if job_id is None and step_id is None and outcome_id is None:
        return
    drafts = drafts_from_batch(batch, job_id=job_id, step_id=step_id, outcome_id=outcome_id)
    for draft in drafts:
        typer.echo(
            render_saved(
                "created",
                run_tool(
                    "add_evidence",
                    {
                        "source_name": draft.source_name,
                        "source_kind": draft.source_kind,
                        "item_type": draft.item_type,
                        "name": draft.name,
                        "content": draft.content,
                        "raw": draft.raw,
                        "job_id": draft.job_id,
                        "step_id": draft.step_id,
                        "outcome_id": draft.outcome_id,
                    },
                ),
                as_json=False,
                noun="Evidence",
            )
        )

/* eslint-disable react-refresh/only-export-components -- context module intentionally exports the hook and constants alongside the provider */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import {
  addOutcome as apiAddOutcome,
  addStep as apiAddStep,
  fetchCanvas,
  fetchConfig,
  healthLlm,
  healthMcp,
  streamChat,
} from "../api/studioApi";
import type { RawSseEvent } from "../api/sse";
import type {
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  ChatMessage,
  StudioConfig,
} from "../types";

const SETTINGS_KEY = "studio.settings";
const CANVAS_KEY = "studio.canvas";
const ENGAGEMENT_KEY = "studio.engagementLevel";

export const WELCOME_MESSAGE =
  "Welcome to **The Living Studio**. We have eliminated backlogs and Jira spreadsheets.\n\n" +
  "You are looking at a living map of human progress. Tell me what your customers are struggling with, " +
  "or click on any outcome on the canvas to inspect its causality.";

export const EMPTY_CONFIG: StudioConfig = {
  base_url: "http://localhost:8001/v1",
  api_key: "local",
  model_name: "local-tools-model",
  mcp_url: "http://localhost:8000/mcp",
};

export type ToastKind = "success" | "error" | "info";

export interface Toast {
  id: number;
  kind: ToastKind;
  message: string;
}

export interface ToolActivity {
  name: string;
  status: string;
  preview?: string;
}

export interface StudioContextValue {
  settings: StudioConfig;
  saveSettings: (config: StudioConfig) => void;
  engagementLevel: number;
  setEngagementLevel: (level: number) => void;
  canvas: CanvasData | null;
  canvasLoading: boolean;
  canvasCached: boolean;
  refreshCanvas: () => Promise<void>;
  llmHealth: { healthy: boolean | null; message: string };
  mcpReachable: boolean;
  messages: ChatMessage[];
  streaming: boolean;
  thinkingPhase: string | null;
  toolActivity: ToolActivity[];
  sendMessage: (text: string) => Promise<void>;
  clearChat: () => void;
  addStep: (payload: Omit<AddStepPayload, "mcp_url">) => Promise<void>;
  addOutcome: (payload: Omit<AddOutcomePayload, "mcp_url">) => Promise<void>;
  pendingSimOutcome: string | null;
  requestSimulate: (outcomeId: string) => void;
  clearPendingSimOutcome: () => void;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  toasts: Toast[];
  pushToast: (kind: ToastKind, message: string) => void;
  dismissToast: (id: number) => void;
}

const StudioContext = createContext<StudioContextValue | null>(null);

function loadSettings(): StudioConfig {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      return { ...EMPTY_CONFIG, ...(JSON.parse(raw) as Partial<StudioConfig>) };
    }
  } catch {
    /* ignore malformed cache */
  }
  return EMPTY_CONFIG;
}

function loadCanvasCache(): CanvasData | null {
  try {
    const raw = localStorage.getItem(CANVAS_KEY);
    if (raw) {
      return JSON.parse(raw) as CanvasData;
    }
  } catch {
    /* ignore malformed cache */
  }
  return null;
}

function loadEngagementLevel(): number {
  try {
    const raw = localStorage.getItem(ENGAGEMENT_KEY);
    if (raw) {
      return Math.max(0, Math.min(2, parseInt(raw, 10)));
    }
  } catch {
    /* ignore malformed cache */
  }
  return 0;
}

export function StudioProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<StudioConfig>(loadSettings);
  const [canvas, setCanvas] = useState<CanvasData | null>(loadCanvasCache);
  const [canvasLoading, setCanvasLoading] = useState(false);
  const [canvasCached, setCanvasCached] = useState(() => loadCanvasCache() !== null);
  const [engagementLevel, setEngagementLevel] = useState(() => loadEngagementLevel());
  const [llmHealth, setLlmHealth] = useState<{ healthy: boolean | null; message: string }>({
    healthy: null,
    message: "Health not checked yet.",
  });
  const [mcpReachable, setMcpReachable] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: "assistant", content: WELCOME_MESSAGE },
  ]);
  const [streaming, setStreaming] = useState(false);
  const [thinkingPhase, setThinkingPhase] = useState<string | null>(null);
  const [toolActivity, setToolActivity] = useState<ToolActivity[]>([]);
  const [pendingSimOutcome, setPendingSimOutcome] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("landscape");
  const [toasts, setToasts] = useState<Toast[]>([]);
  const toastId = useRef(0);
  const abortRef = useRef<AbortController | null>(null);

  const pushToast = useCallback((kind: ToastKind, message: string) => {
    const id = (toastId.current += 1);
    setToasts((prev) => [...prev, { id, kind, message }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((toast) => toast.id !== id));
    }, 6000);
  }, []);

  const dismissToast = useCallback((id: number) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  const saveSettings = useCallback((config: StudioConfig) => {
    setSettings(config);
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(config));
    } catch {
      /* storage unavailable */
    }
  }, []);

  const saveEngagementLevel = useCallback((level: number) => {
    setEngagementLevel(level);
    try {
      localStorage.setItem(ENGAGEMENT_KEY, String(level));
    } catch {
      /* storage unavailable */
    }
  }, []);

  const refreshCanvas = useCallback(async () => {
    setCanvasLoading(true);
    try {
      const data = await fetchCanvas(settings.mcp_url);
      setCanvas(data);
      setCanvasCached(false);
      try {
        localStorage.setItem(CANVAS_KEY, JSON.stringify(data));
      } catch {
        /* storage unavailable */
      }
    } catch (error) {
      pushToast("error", `Canvas sync failed: ${(error as Error).message}`);
    } finally {
      setCanvasLoading(false);
    }
  }, [settings.mcp_url, pushToast]);

  const addStep = useCallback(
    async (payload: Omit<AddStepPayload, "mcp_url">) => {
      try {
        await apiAddStep({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Step added to Job Map!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error adding step: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const addOutcome = useCallback(
    async (payload: Omit<AddOutcomePayload, "mcp_url">) => {
      try {
        await apiAddOutcome({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Outcome captured successfully!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error capturing outcome: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const clearPendingSimOutcome = useCallback(() => setPendingSimOutcome(null), []);

  const requestSimulate = useCallback((outcomeId: string) => {
    setPendingSimOutcome(outcomeId);
    setActiveTab("impact");
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || streaming) {
        return;
      }

      const history: ChatMessage[] = [...messages, { role: "user", content: trimmed }];
      setMessages([...history, { role: "assistant", content: "" }]);
      setStreaming(true);
      setThinkingPhase("health_check");
      setToolActivity([]);

      const controller = new AbortController();
      abortRef.current = controller;

      let content = "";

      const handleEvent = (event: RawSseEvent) => {
        switch (event.event) {
          case "status":
            setThinkingPhase(String(event.data.phase ?? ""));
            break;
          case "delta": {
            content += String(event.data.text ?? "");
            setMessages((prev) => {
              const next = [...prev];
              next[next.length - 1] = { role: "assistant", content };
              return next;
            });
            break;
          }
          case "tool":
            setToolActivity((prev) => [
              ...prev,
              {
                name: String(event.data.name ?? ""),
                status: String(event.data.status ?? ""),
                preview: event.data.preview ? String(event.data.preview) : undefined,
              },
            ]);
            break;
          case "message":
            content = String(event.data.content ?? content);
            setMessages((prev) => {
              const next = [...prev];
              next[next.length - 1] = { role: "assistant", content };
              return next;
            });
            break;
          case "canvas_dirty":
            void refreshCanvas();
            break;
          case "error":
            pushToast("error", String(event.data.message ?? "Unknown chat error"));
            break;
          default:
            break;
        }
      };

      try {
        await streamChat(
          {
            base_url: settings.base_url,
            api_key: settings.api_key,
            model: settings.model_name,
            mcp_url: settings.mcp_url,
            messages: history,
          },
          handleEvent,
          controller.signal,
        );
      } catch (error) {
        if ((error as Error).name !== "AbortError") {
          pushToast("error", `Error during assistant completion: ${(error as Error).message}`);
          setMessages((prev) => {
            const next = [...prev];
            if (next.length && next[next.length - 1].content === "") {
              next.pop();
            }
            return next;
          });
        }
      } finally {
        setStreaming(false);
        setThinkingPhase(null);
        abortRef.current = null;
      }
    },
    [messages, streaming, settings, refreshCanvas, pushToast],
  );

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    setMessages([{ role: "assistant", content: WELCOME_MESSAGE }]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled && localStorage.getItem(SETTINGS_KEY) === null) {
          saveSettings(defaults);
        }
      } catch {
        /* sidecar not reachable; keep local fallback defaults */
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      engagementLevel,
      setEngagementLevel: saveEngagementLevel,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      setActiveTab,
      toasts,
      pushToast,
      dismissToast,
    }),
    [
      settings,
      saveSettings,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      engagementLevel,
      saveEngagementLevel,
      toasts,
      pushToast,
      dismissToast,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

