  it("targets the sidecar directly inside Tauri", () => {
    (window as unknown as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ = {};
    expect(apiUrl("/api/config")).toBe(`${SIDECAR_ORIGIN}/api/config`);
