import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import { ChatCopilot } from "./ChatCopilot";

vi.mock("../../state/StudioContext", () => ({
  useStudio: vi.fn(),
}));

import { useStudio, type StudioContextValue } from "../../state/StudioContext";

const baseContext = {
  messages: [],
  streaming: false,
  thinkingPhase: null as string | null,
  toolActivity: [],
  sendMessage: vi.fn(),
  engagementLevel: 0,
  setEngagementLevel: vi.fn(),
  connectorSuggestions: ["notion"] as string[],
  dismissConnectorSuggestion: vi.fn(),
  addConnector: vi.fn().mockResolvedValue({ ok: true, name: "notion" }),
  presets: [
    {
      id: "notion",
      label: "Notion",
      area: "",
      summary: "",
      url: "",
      auth: "",
      env_vars: [],
      headers: {},
      docs: "",
      tools: [],
      is_recommended: true,
    },
  ],
} as unknown as StudioContextValue;

describe("ChatCopilot connector suggestions", () => {
  it("renders a suggestion chip per connector and wires add + dismiss", () => {
    const add = vi.fn().mockResolvedValue({ ok: true, name: "notion" });
    const del = vi.fn();
    vi.mocked(useStudio).mockReturnValue({ ...baseContext, addConnector: add, dismissConnectorSuggestion: del });

    render(<ChatCopilot />);

    const chip = screen.getByRole("button", { name: /add notion/i });
    expect(chip).toBeInTheDocument();
    fireEvent.click(chip);
    expect(add).toHaveBeenCalledWith({ preset: "notion" });
    expect(del).toHaveBeenCalledWith("notion");
  });

  it("renders nothing when there are no suggestions", () => {
    vi.mocked(useStudio).mockReturnValue({ ...baseContext, connectorSuggestions: [] });

    render(<ChatCopilot />);

    expect(screen.queryByRole("button", { name: /add notion/i })).not.toBeInTheDocument();
  });
});

